# cloud_ws_auth.rb - WebSocket authentication module for cross-service communication
require 'faye/websocket'
require 'json'
require 'openssl'
require 'base64'
require 'securerandom'

module CloudInfra
  module WebSocket
    class AuthHandler
      HMAC_ALGORITHM = 'sha256'
      TOKEN_EXPIRY = 300 # 5 minutes
      NONCE_CACHE_SIZE = 10000

      def initialize(service_registry, opts = {})
        @service_registry = service_registry
        @shared_secrets = opts[:shared_secrets] || {}
        @nonce_cache = LRUCache.new(NONCE_CACHE_SIZE)
        @active_sessions = {}
        @origin_whitelist = opts[:allowed_origins] || []
        @require_origin_check = opts.fetch(:require_origin_check, true)
      end

      def authenticate_upgrade(env)
        request = Rack::Request.new(env)

        # Extract authentication parameters from upgrade request
        auth_header = env['HTTP_AUTHORIZATION']
        origin = env['HTTP_ORIGIN']
        forwarded_for = env['HTTP_X_FORWARDED_FOR']

        return reject(401, 'Missing authorization') unless auth_header

        # Parse the service token
        token_data = parse_service_token(auth_header)
        return reject(401, 'Invalid token format') unless token_data

        # Verify origin if configured
        if @require_origin_check && !verify_origin(origin, token_data[:service_id])
          return reject(403, 'Origin not allowed')
        end

        # Verify the HMAC signature
        unless verify_signature(token_data)
          return reject(401, 'Invalid signature')
        end

        # Check token freshness
        unless token_fresh?(token_data[:timestamp])
          return reject(401, 'Token expired')
        end

        # Replay protection
        if @nonce_cache.include?(token_data[:nonce])
          return reject(401, 'Nonce reused')
        end
        @nonce_cache.put(token_data[:nonce], true)

        # Establish session
        session_id = SecureRandom.hex(32)
        @active_sessions[session_id] = {
          service_id: token_data[:service_id],
          established_at: Time.now.to_i,
          peer_address: forwarded_for || request.ip
        }

        { status: :authenticated, session_id: session_id, service_id: token_data[:service_id] }
      end

      def handle_message(session_id, raw_message)
        session = @active_sessions[session_id]
        return { error: 'No active session' } unless session

        message = JSON.parse(raw_message)

        # Verify per-message authentication for sensitive operations
        if message['operation_class'] == 'privileged'
          unless verify_message_mac(message, session[:service_id])
            return { error: 'Message authentication failed' }
          end
        end

        dispatch_message(message, session)
      rescue JSON::ParserError
        { error: 'Invalid message format' }
      end

      private

      def parse_service_token(auth_header)
        # Format: ServiceAuth <base64-encoded-json>
        match = auth_header.match(/\AServiceAuth\s+(.+)\z/)
        return nil unless match

        payload = JSON.parse(Base64.decode64(match[1]))
        {
          service_id: payload['service_id'],
          timestamp: payload['timestamp'].to_i,
          nonce: payload['nonce'],
          signature: payload['signature'],
          claims: payload['claims'] || {}
        }
      rescue JSON::ParserError, ArgumentError
        nil
      end

      def verify_signature(token_data)
        service_id = token_data[:service_id]
        secret = @shared_secrets[service_id]
        return false unless secret

        # Reconstruct the signing payload including claims
        claims_canonical = (token_data[:claims] || {}).sort.map { |k,v| "#{k}=#{v}" }.join(',')
        signing_input = "#{token_data[:service_id]}|#{token_data[:timestamp]}|#{token_data[:nonce]}|#{claims_canonical}"

        expected_sig = OpenSSL::HMAC.hexdigest(
          HMAC_ALGORITHM, secret, signing_input
        )

        # Compare signatures
        provided_sig = token_data[:signature]
        timing_safe_compare(expected_sig, provided_sig)
      end

      def timing_safe_compare(a, b)
        return false if a.nil? || b.nil?
        return false if a.bytesize != b.bytesize

        l = a.unpack('C*')
        r = b.unpack('C*')
        result = 0
        l.zip(r) { |x, y| result |= x ^ y }
        result == 0
      end

      def verify_origin(origin, service_id)
        return true if origin.nil? && internal_service?(service_id)
        return false if origin.nil?

        @origin_whitelist.any? { |allowed| origin_matches?(origin, allowed) }
      end

      def origin_matches?(origin, pattern)
        if pattern.start_with?('*.')
          suffix = pattern[1..] # e.g., ".example.com"
          origin.end_with?(suffix) || origin == pattern[2..]
        else
          origin == pattern
        end
      end

      def internal_service?(service_id)
        @service_registry.internal?(service_id)
      end

      def token_fresh?(timestamp)
        (Time.now.to_i - timestamp).abs <= TOKEN_EXPIRY
      end

      def verify_message_mac(message, service_id)
        mac = message.delete('mac')
        return false unless mac

        secret = @shared_secrets[service_id]
        return false unless secret

        canonical = message.sort.map { |k, v| "#{k}=#{v}" }.join('&')
        expected = OpenSSL::HMAC.hexdigest(HMAC_ALGORITHM, secret, canonical)
        timing_safe_compare(expected, mac)
      end

      def dispatch_message(message, session)
        { status: 'dispatched', operation: message['operation'] }
      end

      def reject(code, reason)
        { status: :rejected, code: code, reason: reason }
      end
    end

    class LRUCache
      def initialize(max_size)
        @max_size = max_size
        @store = {}
      end

      def include?(key)
        @store.key?(key)
      end

      def put(key, value)
        @store.delete(key)
        @store[key] = value
        @store.delete(@store.first[0]) if @store.size > @max_size
      end
    end
  end
end
